    distances = {'Mercury': 1, 'Venus': 2, 'Earth': 3, 'Mars': 4, 'Jupiter': 5, 'Saturn': 6, 'Uranus': 7, 'Neptune': 8}

    if planet1 not in planets or planet2 not in planets:
        return ()

    planet1_pos = distances[planet1]
    planet2_pos = distances[planet2]

    if planet1_pos == planet2_pos:
        return ()

    start = min(planet1_pos, planet2_pos)
    end = max(planet1_pos, planet2_pos)

    result = [planet for planet, pos in distances.items() if start < pos < end]
    result.sort(key=lambda x: distances[x])

    return tuple(result)

